DELETE FROM AUD_TASK_ATTEMPTS WHERE ATTEMPT_ID IN (
SELECT t.ATTEMPT_ID AS row_id FROM AUD_TASK_ATTEMPTS t WHERE (EXISTS (SELECT 1 FROM AUD_PIPELINES_RUN_LOG r JOIN CFG_PIPELINES p ON p.PIPELINE_ID=r.PIPELINE_ID WHERE p.PROJECT_ID=:project_id AND r.STATUS IN ('SUCCESS','FAILED','SKIPPED','CANCELLED') AND r.END_DATE < :cutoff AND EXISTS (SELECT 1 FROM AUD_TASK_RUN_LOG tr WHERE tr.PIPELINE_RUN_ID=r.PIPELINE_RUN_ID AND tr.TASK_RUN_ID=t.TASK_RUN_ID))) AND t.STATUS NOT IN ('QUEUED','CLAIMED','RUNNING') AND (t.LOG_REMOVED_AT IS NOT NULL OR (t.LOG_PATH IS NULL AND t.TASK_LOG IS NULL)) AND NOT EXISTS (SELECT 1 FROM AUD_CONTROL_REQUESTS c JOIN AUD_TASK_RUN_LOG tr ON tr.PIPELINE_RUN_ID=c.PIPELINE_RUN_ID WHERE tr.TASK_RUN_ID=t.TASK_RUN_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_ATTEMPT_ACKNOWLEDGEMENTS incoming WHERE incoming.ATTEMPT_ID=t.ATTEMPT_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_ATTEMPT_LOG_CHUNKS incoming WHERE incoming.ATTEMPT_ID=t.ATTEMPT_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_GATE_DECISIONS incoming WHERE incoming.ATTEMPT_ID=t.ATTEMPT_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_RESOURCE_LOCKS incoming WHERE incoming.ATTEMPT_ID=t.ATTEMPT_ID)
AND NOT EXISTS (SELECT 1 FROM AUD_TASK_ITEMS incoming WHERE incoming.ATTEMPT_ID=t.ATTEMPT_ID)
ORDER BY t.ATTEMPT_ID LIMIT 10000
)
